'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');const root=path.join(__dirname,'..'),H=require('./html-scripts');
function block(html){const script=H.theInlineScript(html),start=script.indexOf('(function(){var ov2=null'),end=script.indexOf('})();',start)+5;if(start<0||end<start)throw Error('shortcuts block missing');return script.slice(start,end);}
function fixture(lang='fr'){
 const html=fs.readFileSync(path.join(root,'index.html'),'utf8'),handlers=[],nodes=[];let active;
 function el(tag,cls,text){const node={tagName:tag.toUpperCase(),className:cls,textContent:text||'',children:[],attrs:{},offsetParent:{},isConnected:true,getClientRects(){return [{width:40,height:20}];},appendChild(child){this.children.push(child);child.parent=this;return child;},setAttribute(k,v){this.attrs[k]=v;},addEventListener(key,fn){this[key]=fn;},focus(){active=this;},remove(){this.isConnected=false;for(const child of this.children)child.isConnected=false;}};nodes.push(node);return node;}
 const trigger=el('button','trigger'),search=el('input','search'),outside=el('button','outside');active=trigger;let background=0;
 const doc={body:el('body','body'),getElementById:id=>id==='ov'?{classList:{contains:()=>false}}:id==='search'?search:null,addEventListener:(key,fn,capture)=>handlers.push({key,fn,capture:!!capture}),get activeElement(){return active;}};
 handlers.push({key:'keydown',capture:false,fn:()=>background++});vm.runInNewContext(block(html),{document:doc,curLang:()=>lang,el,getComputedStyle:node=>node.css||{display:'block',visibility:'visible',opacity:'1'}});
 function key(key,extra={}){let prevented=false,stopped=false;const event={key,target:active,preventDefault:()=>prevented=true,stopImmediatePropagation:()=>stopped=true,...extra};for(const h of handlers.slice().sort((a,b)=>Number(b.capture)-Number(a.capture)))if(h.key==='keydown'&&!stopped)h.fn(event);if(key==='Tab'&&!prevented)active=outside;return {prevented,stopped};}
 return {key,trigger,search,nodes,active:()=>active,background:()=>background,close:()=>nodes.find(n=>n.className==='kbbox')?.children.find(n=>n.tagName==='BUTTON'),overlay:()=>nodes.find(n=>n.className==='kbov')};
}
for(const lang of ['fr','en'])test(lang+' real pane has a translated close button and traps Tab/Shift+Tab',()=>{const f=fixture(lang);f.key('?');const close=f.close();assert.ok(close,'close button exists');assert.equal(close.textContent,lang==='en'?'Close':'Fermer');assert.equal(f.active(),close);assert.equal(f.key('Tab').prevented,true);assert.equal(f.active(),close);assert.equal(f.key('Tab',{shiftKey:true}).prevented,true);assert.equal(f.active(),close);});
for(const method of ['Escape','button','outside'])test('closing by '+method+' restores trigger focus',()=>{const f=fixture();f.key('?');if(method==='Escape')f.key('Escape');else if(method==='button'){assert.ok(f.close());f.close().click({target:f.close()});}else f.overlay().click({target:f.overlay()});assert.equal(f.active(),f.trigger);});
test('background shortcuts cannot steal focus while pane is modal',()=>{const f=fixture();f.key('?');const before=f.background();f.key('/');f.key('k',{ctrlKey:true});assert.equal(f.background(),before);assert.equal(f.active(),f.close());});
test('a removed trigger falls back to visible search',()=>{const f=fixture();f.key('?');f.trigger.isConnected=false;f.key('Escape');assert.equal(f.active(),f.search);});
module.exports={fixture,block};

test('closed pane does not intercept normal Tab',()=>{const f=fixture();assert.equal(f.key('Tab').prevented,false);f.key('?');f.key('Escape');assert.equal(f.key('Tab').prevented,false);});
test('repeated open and close leaves one modal per invocation',()=>{const f=fixture();for(let i=0;i<3;i++){f.key('?');f.key('?');assert.equal(f.nodes.filter(n=>n.className==='kbov'&&n.isConnected).length,1);f.key('Escape');assert.equal(f.nodes.filter(n=>n.className==='kbov'&&n.isConnected).length,0);}});
const {apply}=require('../habillage/shortcuts-accessibility.cjs'),crypto=require('node:crypto');
const ORIGINAL_SHORTCUTS = "(function(){var ov2=null;\n function close(){if(ov2){ov2.remove();ov2=null;}}\n function open(){if(ov2)return;var EN=curLang()==='en';\n  ov2=el('div','kbov');var box=el('div','kbbox');box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label',EN?'Keyboard shortcuts':'Raccourcis clavier');\n  box.appendChild(el('div','kbt',EN?'⌨️ Keyboard shortcuts':'⌨️ Raccourcis clavier'));\n  [[('/'),EN?'focus the search':'aller à la recherche'],\n   ['Ctrl+K',EN?'quick command palette':'palette de commandes rapide'],\n   ['Échap'+(EN?' / Esc':''),EN?'close panels · clear the search':'fermer les panneaux · vider la recherche'],\n   ['Entrée',EN?'open the focused card':'ouvrir la carte sélectionnée'],\n   ['?',EN?'this panel':'ce panneau']].forEach(function(r){\n   var l=el('div','kbrow');l.appendChild(el('kbd',null,r[0]));l.appendChild(el('span',null,r[1]));box.appendChild(l);});\n  ov2.appendChild(box);ov2.addEventListener('click',function(e){if(e.target===ov2)close();});\n  document.body.appendChild(ov2);box.tabIndex=-1;box.focus();}\n document.addEventListener('keydown',function(e){\n  if(e.key==='Escape'){close();return;}\n  if(e.key==='?'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!/^(input|textarea|select)$/i.test((e.target&&e.target.tagName)||'')&&!document.getElementById('ov').classList.contains('open')){e.preventDefault();open();}});})();";
function originalPage(){
 const html=fs.readFileSync(path.join(root,'index.html'),'utf8'),script=H.theInlineScript(html),marker='/* hp:shortcuts-accessibility:v2 */',start=script.indexOf(marker);
 if(start<0)return html;
 const end=script.indexOf('})();',start)+5;assert.ok(end>start);
 const before=script.slice(0,start)+ORIGINAL_SHORTCUTS+script.slice(end);
 const raw=[...html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script\s*>/gi)].filter(m=>H.normalize(m[1])===script);assert.equal(raw.length,1);
 const sha=s=>crypto.createHash('sha256').update(s).digest('base64');
 return html.replace(raw[0][1],()=>before).replace("'sha256-"+sha(script)+"'","'sha256-"+sha(before)+"'");
}

function withoutBlock(html){const body=H.theInlineScript(html),start=body.indexOf('/* hp:shortcuts-accessibility:v2 */');if(start>=0){const end=body.indexOf('})();',start)+5;return body.slice(0,start)+body.slice(end);}const begin=body.indexOf('(function(){var ov2=null;'),end=body.indexOf('})();',begin)+5;return body.slice(0,begin)+body.slice(end);}
test('transform preserves unrelated script and page bytes and is idempotent',()=>{const before=originalPage(),after=apply(before);assert.equal(apply(after),after);assert.equal(withoutBlock(after),withoutBlock(before));const strip=h=>h.replace(/<script\b[^>]*>[\s\S]*?<\/script\s*>/gi,'SCRIPT').replace(/'sha256-[A-Za-z0-9+/=]+'/g,'HASH');assert.equal(strip(after),strip(before));assert.equal(after,fs.readFileSync(path.join(root,'index.html'),'utf8'));});
test('CRLF preservation and CSP hash match browser normalization',()=>{const before=originalPage().replace(/\r?\n/g,'\r\n'),after=apply(before);assert.equal((after.match(/(?<!\r)\n/g)||[]).length,0);const hash=crypto.createHash('sha256').update(H.theInlineScript(after)).digest('base64');assert.ok(after.includes("'sha256-"+hash+"'"));assert.equal(apply(after),after);});
test('unknown or missing CSP authorization refuses without weakening CSP',()=>{const before=originalPage(),hash=crypto.createHash('sha256').update(H.theInlineScript(before)).digest('base64');assert.throws(()=>apply(before.replace(hash,'invalid')));const after=apply(before);assert.equal((after.match(/unsafe-inline/g)||[]).length,(before.match(/unsafe-inline/g)||[]).length);assert.equal((after.match(/unsafe-eval/g)||[]).length,(before.match(/unsafe-eval/g)||[]).length);});
test('a misleading marker or duplicate active script refuses',()=>{const before=originalPage();assert.throws(()=>apply(before.replace('(function(){var ov2=null;','/* hp:shortcuts-accessibility:v2 */ (function(){var ov2=null;')));assert.throws(()=>apply(before.replace('</body>','<script>console.log(1)</script></body>')));});

test('a visible fixed-position trigger with offsetParent null receives focus back',()=>{const f=fixture();f.trigger.offsetParent=null;f.key('?');f.key('Escape');assert.equal(f.active(),f.trigger);});
test('a trigger without rendered rectangles is not focused',()=>{const f=fixture();f.key('?');f.trigger.getClientRects=()=>[];f.key('Escape');assert.equal(f.active(),f.search);});
for(const css of [{visibility:'hidden',display:'block',opacity:'1'},{visibility:'visible',display:'none',opacity:'1'},{visibility:'visible',display:'block',opacity:'0'}])test('an invisible trigger is not restored '+JSON.stringify(css),()=>{const f=fixture();f.key('?');f.trigger.css=css;f.key('Escape');assert.equal(f.active(),f.search);});
test('a disabled trigger falls back to search',()=>{const f=fixture();f.key('?');f.trigger.disabled=true;f.key('Escape');assert.equal(f.active(),f.search);});
